// Writes the database as the addon's Data.lua. Each profession's recipes and items are kept as
// text, one line each, fields separated by tabs, and only turned into tables when the profession
// is first looked at in game (Core.lua's decode): loading text is cheap, thousands of tables
// aren't, so the game doesn't pay for professions nobody opens. Core.lua reads this format: keep
// the two in step (dev/GuildAssistantDatabase's specs load a generated file).
//
// Recipe line: spell id, name, skill to learn, skill-up colours ("yellow,green,grey"), item made
//   ("id,min,max", empty for an enchant), reagents ("id:count;…"), Wowhead's source codes ("6;2"),
//   trainer's cost in copper, recipe items ("id;…").
// Item line: id, name, quality, required level, inventory type, icon, summary (slot and stats),
//   skill to use (recipe items), sources ("<kind><zone>=<name>;…", kind D drop, V vendor,
//   Q quest, O object; zone 0 when unknown).

const KINDS = { drop: 'D', vendor: 'V', quest: 'Q', object: 'O' };

/** Text that fits in a field: no tabs, line breaks or list separators. */
const field = (text) => String(text ?? '').replace(/[\t\r\n;]+/g, ' ').replace(/ {2,}/g, ' ').trim();

export function recipeLine(recipe) {
  return [
    recipe.id,
    field(recipe.name),
    recipe.skill,
    recipe.colors.join(','),
    recipe.creates ? `${recipe.creates.id},${recipe.creates.min},${recipe.creates.max}` : '',
    recipe.reagents.map((r) => `${r.id}:${r.count}`).join(';'),
    recipe.sources.join(';'),
    recipe.trainingCost || '',
    recipe.recipeItems.join(';'),
  ].join('\t');
}

export function itemLine(item) {
  return [
    item.id,
    field(item.name),
    item.quality,
    item.level || '',
    item.slot || '',
    field(item.icon),
    field(item.summary),
    item.skill || '',
    item.sources.map((s) => `${KINDS[s.kind]}${s.zone || 0}=${field(s.name)}`).join(';'),
  ].join('\t');
}

/** A Lua long string holding `text`, with a level of "=" that doesn't occur in it. */
export function longString(text) {
  let level = '';
  while (text.includes(`]${level}]`)) level += '=';
  // A long string drops a line break right after its opening bracket: start with one.
  return `[${level}[\n${text}]${level}]`;
}

const quote = (text) => JSON.stringify(String(text)); // a JSON string is a valid Lua one here

/** The whole Data.lua for `database` (buildDatabase's result). */
export function toLua(database) {
  const lines = [
    `-- GuildAssistant Database: recipe data from Wowhead (${database.version}), fetched ${database.fetched}.`,
    '-- Generated by `npm run database` in addons/ (scripts/database): don\'t edit it by hand.',
    '',
    'local _, ns = ...',
    'ns.Data = {',
    `    version = ${quote(database.version)},`,
    `    fetched = ${quote(database.fetched)},`,
    '    professions = {',
  ];
  for (const profession of database.professions) {
    lines.push(
      '        {',
      `            name = ${quote(profession.name)}, skill = ${profession.skill}, count = ${profession.recipes.length},`,
      `            recipes = ${longString(profession.recipes.map(recipeLine).join('\n'))},`,
      `            items = ${longString(profession.items.map(itemLine).join('\n'))},`,
      '        },',
    );
  }
  lines.push('    },', '}', '');
  return lines.join('\n');
}
